pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 initVal) internal {
        vm.assume(true);
        try c.Initialized() {} catch { return; }
        bool reverted;
        try c.SetMinSum(initVal) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted && c.MinSum() == 0);
    }

    function testFuzz_run(uint256 initVal) public {
        _run(initVal);
    }

    receive() external payable {}
}
